/* MODULE kh10 · Bước 2 Hiểu khách hàng · Gen Z, phụ huynh, người tỉnh: ba nhóm hay bị hiểu sai
   10 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'kh10', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:kh10-01', skill:'insight', read:'6 phút', t:'Gen Z chỉ thích bắt trend — hay bạn đang nhìn nhầm lý do?',
  situation:'Một hãng trà sữa ở Hà Nội ra ly "trend" theo một meme đang hot, giá 45.000đ. Tuần đầu bán 600 ly, tuần thứ ba còn 90 ly. Cùng lúc, một món cũ có trân châu làm tươi mỗi ngày vẫn đều 400 ly mỗi tuần, chủ yếu khách 18–24 tuổi. Sếp kết luận: "Gen Z cả thèm chóng chán, phải ra trend liên tục."',
  concept:{ name:'Thử vì tò mò, ở lại vì lý do thật',
    body:'Trend tạo ra <b>lần thử đầu tiên</b>: người trẻ muốn biết món đó thế nào, muốn chụp ảnh, muốn có chuyện để nói với bạn. Nhưng lần mua lặp lại cần một lý do bền: ngon hơn, đáng tiền hơn, hợp thói quen hơn. Gọi Gen Z là "chỉ thích trend" là trộn hai hành vi khác nhau thành một. Cách đọc đúng: tách khách <b>thử</b> khỏi khách <b>quay lại</b>, rồi hỏi mỗi nhóm đang mua vì điều gì.' },
  example:'Ly trend: 600 ly tuần đầu, 90 ly tuần ba — giữ lại 15%. Món trân châu tươi: 400 ly đều đặn, khảo sát tại quầy cho thấy phần lớn là khách quen mua 2–3 lần mỗi tuần. Kết luận đúng không phải "ra trend liên tục" mà là: dùng trend để kéo người mới vào quán, rồi mời họ thử món có lý do ở lại. Tuần sau, quầy tặng một ly nhỏ trân châu tươi cho ai mua ly trend.',
  takeaway:'Trend mở cửa, chất lượng giữ chân: đừng lấy lượt thử làm bằng chứng cho tính cách cả một thế hệ.',
  apply:'Nghĩ tới một món bạn từng thử vì trend. Nói trong 60 giây: bạn có mua lại không, và lý do mua lại (hoặc bỏ) là gì.',
  mistakes:['Lấy doanh số tuần đầu của món trend làm thước đo sở thích của Gen Z.','Kết luận "cả thèm chóng chán" mà không nhìn nhóm khách quay lại.'],
  q:[
  { type:'mcq', stem:'Ly trend bán 600 ly tuần đầu rồi tụt còn 90 ly. Đoán trước: điều này nói gì nhiều nhất?',
    options:[{k:'a',t:'Trend kéo được người thử, nhưng món chưa có lý do để mua lại'},{k:'b',t:'Gen Z chán nhanh hơn mọi nhóm tuổi khác, nên không thể giữ chân được'},
             {k:'c',t:'Giá 45.000đ quá cao so với túi tiền người trẻ nên họ bỏ đi'},{k:'d',t:'Meme hết hot, cần đổi sang meme khác thì doanh số sẽ quay lại'}],
    answer:'a', why:{a:'Đúng. Hai con số đo hai hành vi khác nhau: thử và mua lại. Món trend làm tốt việc đầu, hỏng việc sau.',
      b:'Món trân châu tươi vẫn giữ 400 ly/tuần với cùng nhóm khách — vậy họ không chán mọi thứ.',
      c:'Nếu giá là vấn đề, tuần đầu đã không bán được 600 ly ở cùng mức giá.',
      d:'Đổi meme chỉ lặp lại vòng thử – bỏ, không giải quyết chuyện khách không quay lại.'} },
  { type:'mcq', stem:'Sếp muốn mỗi tháng ra 2 món trend mới. Bạn đề xuất gì?',
    options:[{k:'a',t:'Làm theo sếp, vì người trẻ chỉ phản ứng với cái mới, không cần bàn thêm'},{k:'b',t:'Bỏ hẳn món trend, tập trung toàn bộ ngân sách vào món trân châu tươi'},
             {k:'c',t:'Hạ giá món trend xuống 30.000đ để kéo doanh số tuần ba lên lại'},{k:'d',t:'Giữ trend để kéo khách mới, gắn với ưu đãi thử món có khách quen'}],
    answer:'d', why:{a:'Dữ liệu cho thấy món có lý do bền mới giữ doanh số; ra trend liên tục chỉ đổ chi phí phát triển món.',
      b:'Trend vẫn có giá trị: nó kéo người mới vào quán. Bỏ hẳn là mất cửa vào.',
      c:'Giảm giá không tạo ra lý do quay lại; chỉ làm mỏng lãi của một món đang yếu.',
      d:'Đúng. Dùng trend làm cửa vào, rồi dẫn khách sang món có lý do mua lại.'} },
  { type:'calc', stem:'Ly trend bán 600 ly tuần đầu và 90 ly tuần thứ ba. Doanh số tuần ba bằng bao nhiêu phần trăm tuần đầu?',
    unit:'%', ans:15, tol:0.1, wrong:[[85,'NHAM_TI_LE_ROI'],[666.7,'SAI_MAU_SO']], errors:['NHAM_TI_LE_ROI','SAI_MAU_SO'],
    steps:['Tỉ lệ giữ lại = tuần ba ÷ tuần đầu.','90 ÷ 600 = 0,15 = <b>15%</b> (tức là mất 85%).'] },
  { type:'mcq', stem:'Một quán cà phê thấy khách 20 tuổi đến đông khi có góc chụp ảnh mới, nhưng số khách quen không tăng. Nên đọc thế nào?',
    options:[{k:'a',t:'Góc chụp ảnh vô ích, nên dỡ bỏ để tiết kiệm mặt bằng'},{k:'b',t:'Góc ảnh kéo lượt thử; cần tìm vì sao họ không quay lại'},
             {k:'c',t:'Khách trẻ chỉ đến để chụp ảnh, không bao giờ trở thành khách quen'},{k:'d',t:'Cần làm góc chụp ảnh mới mỗi tuần để giữ lượng khách đông như vậy'}],
    answer:'b', why:{a:'Góc ảnh đã làm tốt việc kéo người mới; dỡ bỏ là mất cửa vào.',
      b:'Đúng. Tách lượt thử khỏi lượt quay lại, rồi tìm lý do ở lại (đồ uống, chỗ ngồi, giá…).',
      c:'Đó là khuôn mẫu; nhiều người trẻ là khách quen của quán có lý do để quay lại.',
      d:'Đổi góc ảnh liên tục chỉ lặp lại lượt thử, tốn tiền mà không tạo khách quen.'} },
  { type:'mcq', stem:'Chỉ số nào giúp bạn kiểm tra nhận định "Gen Z cả thèm chóng chán" tốt nhất?',
    options:[{k:'a',t:'Số lượt xem video TikTok về món trend trong tuần đầu ra mắt'},{k:'b',t:'Tổng doanh số tháng của toàn quán, so với cùng kỳ năm ngoái'},
             {k:'c',t:'Tỉ lệ khách trẻ mua lại trong 30 ngày, tách theo từng món'},{k:'d',t:'Số người theo dõi fanpage tăng thêm sau mỗi đợt ra món trend'}],
    answer:'c', why:{a:'Lượt xem đo sự chú ý, không đo hành vi quay lại.',
      b:'Tổng doanh số trộn mọi nhóm khách và mọi món; không trả lời được câu hỏi.',
      c:'Đúng. Mua lại theo món cho thấy nhóm này ở lại với món nào và bỏ món nào.',
      d:'Lượt theo dõi là tín hiệu quan tâm, không phải bằng chứng mua lại.'} },
  { type:'mcq', stem:'Một bạn trong nhóm nói: "Người trẻ bây giờ không trung thành với thương hiệu nào cả." Phản biện nào có căn cứ nhất?',
    options:[{k:'a',t:'Họ vẫn trung thành, nhưng với thứ cho họ lý do cụ thể để quay lại'},{k:'b',t:'Đúng vậy, nên thương hiệu chỉ cần tối ưu lượt mua đầu tiên là đủ'},
             {k:'c',t:'Họ trung thành với người nổi tiếng, không phải với sản phẩm hay quán'},{k:'d',t:'Họ trung thành với hãng rẻ nhất trong ngành hàng, bất kể chất lượng'}],
    answer:'a', why:{a:'Đúng. Món trân châu tươi giữ 400 ly/tuần là bằng chứng: có lý do thì có khách quen.',
      b:'Bỏ qua mua lại là bỏ phần doanh thu ổn định nhất của quán.',
      c:'KOL có thể kéo lượt thử, nhưng không giải thích được khách quen của món cũ.',
      d:'Món được giữ chân ở đây không phải món rẻ nhất; giá không phải lý do duy nhất.'} },
  { type:'mcq', stem:'Bạn cần viết một câu insight về khách trẻ của quán cho buổi họp. Câu nào tốt nhất?',
    options:[{k:'a',t:'Gen Z thích cái mới, thích sống ảo và luôn chạy theo trend'},{k:'b',t:'Khách trẻ nhạy cảm về giá nên cần khuyến mãi liên tục để giữ'},
             {k:'c',t:'Khách trẻ thử vì tò mò, nhưng chỉ quay lại khi món thật sự đáng tiền'},{k:'d',t:'Khách trẻ mua theo bạn bè, nên chỉ cần làm chương trình rủ bạn đi cùng'}],
    answer:'c', why:{a:'Đây là khuôn mẫu, không dẫn tới quyết định nào khác ngoài "ra trend".',
      b:'Dữ liệu không cho thấy giá là lý do; món giữ chân không phải món rẻ.',
      c:'Đúng. Câu này tách thử và quay lại, và gợi ý việc cần làm.',
      d:'Rủ bạn có thể giúp lượt thử, nhưng không giải thích vì sao họ bỏ món trend.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:kh10-02', skill:'insight', read:'7 phút', t:'Sinh viên ít tiền thì chỉ mua đồ rẻ nhất?',
  situation:'Một nhãn tai nghe nội địa định giá 290.000đ để "vừa túi sinh viên". Bán chậm. Khảo sát 50 sinh viên cho thấy nhiều bạn đang dùng tai nghe 1.200.000đ, mua bằng cách để dành 3 tháng, nhưng ăn trưa 25.000đ mỗi ngày và đi xe buýt. Nhóm marketing bối rối: sinh viên nghèo hay không nghèo?',
  concept:{ name:'Chi tiêu có chọn lọc (tiết kiệm chỗ này, xài sang chỗ kia)',
    body:'Người có ít tiền không chia đều sự tiết kiệm cho mọi thứ. Họ <b>cắt mạnh</b> ở hạng mục không quan trọng với mình (bữa trưa, đi lại) để <b>chi mạnh</b> cho vài thứ gắn với bản thân: điện thoại, tai nghe, đồ chơi sở thích, một chuyến đi. Câu hỏi đúng không phải "họ có bao nhiêu tiền" mà là "hạng mục của mình nằm ở phía họ cắt hay phía họ để dành để mua".' },
  example:'Tai nghe là thứ sinh viên đeo 6 tiếng mỗi ngày, bạn bè nhìn thấy, gắn với âm nhạc — nằm ở phía "đáng để dành". Giá 290.000đ lại phát tín hiệu "đồ tạm". Nếu bạn để dành 400.000đ mỗi tháng trong 3 tháng, bạn có 1.200.000đ và muốn một món xứng với ba tháng nhịn. Nhãn đổi hướng: ra bản 790.000đ chất lượng tốt hơn, cho trả góp 0% qua ví điện tử, nói rõ thông số thay vì nói "giá rẻ".',
  takeaway:'Ít tiền không có nghĩa là mua rẻ mọi thứ: tìm xem sản phẩm của bạn nằm ở phía họ cắt hay phía họ để dành.',
  apply:'Liệt kê 3 thứ bạn tiết kiệm triệt để và 1 thứ bạn sẵn sàng chi mạnh. Nói trong 60 giây vì sao thứ đó đáng.',
  mistakes:['Suy ra mức chi của mọi hạng mục từ thu nhập trung bình.','Dùng chữ "giá rẻ" làm thông điệp chính cho một món khách coi là đáng đầu tư.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao sinh viên ăn trưa 25.000đ lại dùng tai nghe 1.200.000đ?',
    options:[{k:'a',t:'Họ được bố mẹ mua cho nên không phải tự bỏ tiền ra'},{k:'b',t:'Họ cắt chỗ ít quan trọng để dồn tiền vào thứ gắn với bản thân'},
             {k:'c',t:'Họ chi tiêu thiếu kế hoạch, thấy gì thích là mua ngay lập tức'},{k:'d',t:'Tai nghe đắt là hàng trả góp, nên thật ra họ không chịu chi phí đó'}],
    answer:'b', why:{a:'Khảo sát cho thấy nhiều bạn tự để dành 3 tháng; quy cho bố mẹ là bỏ qua dữ kiện.',
      b:'Đúng. Đây là chi tiêu có chọn lọc: tiết kiệm ở bữa trưa để dành cho món quan trọng.',
      c:'Để dành 3 tháng là hành vi có kế hoạch, ngược với mua bốc đồng.',
      d:'Trả góp vẫn là họ trả đủ; nó chỉ chia nhỏ, không xoá chi phí.'} },
  { type:'mcq', stem:'Tai nghe 290.000đ bán chậm với sinh viên. Bạn sửa gì trước?',
    options:[{k:'a',t:'Hạ tiếp xuống 199.000đ để thật sự là rẻ nhất trên thị trường'},{k:'b',t:'Tăng ngân sách quảng cáo, vì bán chậm là do sinh viên chưa biết tới'},
             {k:'c',t:'Chuyển sang bán cho người đi làm, vì sinh viên không có tiền'},{k:'d',t:'Ra bản tốt hơn ở giá cao hơn, kèm trả góp và thông số rõ ràng'}],
    answer:'d', why:{a:'Rẻ hơn càng khẳng định hình ảnh "đồ tạm" ở hạng mục khách muốn chi mạnh.',
      b:'Chưa rõ vấn đề là nhận biết; dữ liệu cho thấy vấn đề là định vị giá.',
      c:'Sinh viên đang chi 1.200.000đ cho tai nghe; họ có tiền cho thứ họ coi là đáng.',
      d:'Đúng. Đặt sản phẩm vào phía "đáng để dành" và giảm rào cản thanh toán.'} },
  { type:'calc', stem:'Một sinh viên để dành 400.000đ mỗi tháng. Cần bao nhiêu tháng để mua tai nghe 1.200.000đ?',
    unit:'tháng', ans:3, tol:0.01, wrong:[[0.33,'SAI_MAU_SO'],[4.8,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Số tháng = giá món ÷ số tiền để dành mỗi tháng.','1.200.000 ÷ 400.000 = <b>3 tháng</b>.'] },
  { type:'mcq', stem:'Một hãng mỹ phẩm thấy sinh viên mua son 350.000đ nhưng chọn dầu gội loại rẻ nhất. Kết luận nào hợp lý?',
    options:[{k:'a',t:'Son gắn với hình ảnh bản thân nên họ chi mạnh; dầu gội thì không'},{k:'b',t:'Sinh viên thật ra có nhiều tiền, chỉ là dầu gội đắt thì vô lý'},
             {k:'c',t:'Hãng dầu gội nên định giá thấp hơn nữa để lấy trọn thị phần'},{k:'d',t:'Son đang giảm giá mạnh nên họ mua, còn bình thường thì không'}],
    answer:'a', why:{a:'Đúng. Cùng một người, hai hạng mục, hai cách chi — đúng mô hình chọn lọc.',
      b:'Họ không nhiều tiền; họ phân bổ tiền theo mức quan trọng.',
      c:'Kết luận này chưa được dữ kiện hỗ trợ; có thể họ cần lý do khác để nâng cấp.',
      d:'Không có dữ kiện về giảm giá; đây là suy diễn thêm.'} },
  { type:'mcq', stem:'Thông điệp nào hợp nhất cho tai nghe 790.000đ gửi tới sinh viên?',
    options:[{k:'a',t:'"Rẻ nhất phân khúc — sinh viên nào cũng mua được"'},{k:'b',t:'"Chất âm như hàng 2 triệu, trả góp 0%, 263.000đ/tháng"'},
             {k:'c',t:'"Tai nghe cao cấp dành cho người thành đạt, sang trọng"'},{k:'d',t:'"Giảm 50% hôm nay, số lượng có hạn, mua ngay kẻo lỡ"'}],
    answer:'b', why:{a:'Nhấn "rẻ" kéo món về phía đồ tạm, ngược với lý do khách muốn chi.',
      b:'Đúng. Nói giá trị cụ thể và chia nhỏ khoản chi cho vừa dòng tiền để dành.',
      c:'Nói với người thành đạt là nói sai người; sinh viên không thấy mình trong đó.',
      d:'Giảm sốc làm khách nghi chất lượng và dạy họ chờ giảm giá.'} },
  { type:'mcq', stem:'Khi làm chân dung khách sinh viên, câu hỏi nào nên thêm vào khảo sát?',
    options:[{k:'a',t:'Bạn nhận được bao nhiêu tiền mỗi tháng từ gia đình và từ đi làm thêm?'},{k:'b',t:'Bạn thích thương hiệu tai nghe nào nhất trong các hãng hiện nay?'},
             {k:'c',t:'Bạn sẵn lòng nhịn khoản nào để có tiền mua món mình muốn?'},{k:'d',t:'Bạn có hay theo dõi các trend âm nhạc mới trên mạng xã hội không?'}],
    answer:'c', why:{a:'Thu nhập chỉ cho mức tổng, không cho biết họ dồn tiền vào đâu.',
      b:'Câu này đo sở thích hãng, không lộ ra cơ chế chi tiêu.',
      c:'Đúng. Câu này chỉ ra hạng mục họ cắt và hạng mục họ để dành.',
      d:'Sở thích âm nhạc có ích cho sáng tạo, nhưng không trả lời chuyện chi tiêu.'} },
  { type:'mcq', stem:'Sếp hỏi: "Vậy mình có nên bán đắt cho sinh viên không?" Câu trả lời đúng tinh thần bài nhất?',
    options:[{k:'a',t:'Có — sinh viên luôn sẵn sàng trả nhiều hơn nếu thương hiệu đủ nổi tiếng'},{k:'b',t:'Không — sinh viên ít tiền nên mọi mức giá cao đều sẽ thất bại'},
             {k:'c',t:'Chỉ khi món thuộc nhóm họ chi mạnh, và giá phải đi kèm giá trị rõ'},{k:'d',t:'Chỉ nên bán đắt vào dịp đầu năm học khi sinh viên vừa nhận tiền'}],
    answer:'c', why:{a:'Nổi tiếng không đủ; với hạng mục họ cắt, họ vẫn chọn rẻ.',
      b:'Họ vẫn chi mạnh cho món quan trọng; "mọi" là quá tay.',
      c:'Đúng. Giá cao chỉ hợp khi món nằm ở phía "đáng để dành" và giá trị thấy được.',
      d:'Thời điểm có ảnh hưởng, nhưng không phải điều kiện quyết định.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:kh10-03', skill:'creative', read:'6 phút', t:'Vì sao video "chuyên nghiệp" lại thua video quay bằng điện thoại?',
  situation:'Một hãng giày thể thao làm hai video cho khách 18–25 tuổi. Video A quay studio, người mẫu, nhạc sôi động, tốn 80 triệu. Video B là một bạn nhân viên quay bằng điện thoại, chạy thử giày trên đường Nguyễn Huệ, nói thật "đế hơi cứng hai ngày đầu". Sau 7 ngày, video B có tỉ lệ xem hết 32%, video A 9%.',
  concept:{ name:'Dị ứng với "làm màu" (tín hiệu thật)',
    body:'Người trẻ lớn lên giữa quảng cáo, nên nhận ra rất nhanh cái gì <b>được dàn dựng để bán</b>. Họ không ghét quảng cáo; họ ghét cảm giác bị coi là dễ lừa. Tín hiệu thật gồm: người giống họ, bối cảnh quen, nói cả điểm chưa hoàn hảo, không hứa quá. Một điểm yếu nói thật làm các điểm mạnh đáng tin hơn. "Thật" không có nghĩa là cẩu thả: âm thanh vẫn phải nghe rõ, thông tin vẫn phải đúng.' },
  example:'Video B nói "đế hơi cứng hai ngày đầu, sau đó êm" — một câu mà video studio không bao giờ nói. Bình luận hỏi size, hỏi đường chạy, hỏi giá. Video A nhận bình luận "quảng cáo à". Với 80 triệu, hãng có thể làm 10 video kiểu B, mỗi video 8 triệu, thử nhiều người và nhiều bối cảnh.',
  takeaway:'Với người trẻ, một điểm yếu nói thật đáng giá hơn mười lời khen được dàn dựng.',
  apply:'Chọn một sản phẩm bạn dùng. Nói trong 60 giây một điểm chưa hoàn hảo của nó và vì sao bạn vẫn dùng.',
  mistakes:['Tưởng "thật" nghĩa là quay ẩu, âm thanh kém, thông tin sai.','Dựng một video "như thật" nhưng kịch bản vẫn chỉ toàn khen.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao video quay điện thoại có tỉ lệ xem hết cao gấp hơn ba lần video studio?',
    options:[{k:'a',t:'Người xem nhận ra video studio là dàn dựng để bán nên lướt qua'},{k:'b',t:'Thuật toán TikTok luôn ưu tiên video quay bằng điện thoại'},
             {k:'c',t:'Video điện thoại ngắn hơn nên đương nhiên được xem hết nhiều hơn'},{k:'d',t:'Nguyễn Huệ là địa điểm nổi tiếng nên tự thu hút người xem'}],
    answer:'a', why:{a:'Đúng. Tín hiệu dàn dựng làm người xem trẻ rời đi sớm; tín hiệu thật giữ họ lại.',
      b:'Không có căn cứ rằng nền tảng chấm điểm theo thiết bị quay.',
      c:'Tình huống không nói B ngắn hơn; đây là giả định thêm.',
      d:'Địa điểm có thể giúp một chút, nhưng không giải thích bình luận hỏi size và giá.'} },
  { type:'mcq', stem:'Bạn còn 80 triệu cho quý sau. Bạn chọn phân bổ thế nào?',
    options:[{k:'a',t:'Làm một video studio lớn hơn, thuê người nổi tiếng để lấn át video B'},{k:'b',t:'Làm nhiều video kiểu B, thử nhiều người thật và bối cảnh khác nhau'},
             {k:'c',t:'Dồn hết 80 triệu chạy quảng cáo cho video B đang thắng'},{k:'d',t:'Quay lại video A nhưng lồng tiếng như người thật để trông gần gũi'}],
    answer:'b', why:{a:'Người nổi tiếng không xoá được cảm giác dàn dựng; vẫn là video A đắt hơn.',
      b:'Đúng. Nhân bản cách làm đang thắng và thử nhiều biến thể để học thêm.',
      c:'Một video sẽ mòn khi chạy nhiều; nên có nhiều biến thể để luân phiên.',
      d:'"Giả thật" dễ bị nhận ra và còn phản tác dụng hơn video studio thẳng thắn.'} },
  { type:'calc', stem:'Ngân sách 80 triệu, mỗi video quay điện thoại tốn 8 triệu. Làm được bao nhiêu video?',
    unit:'video', ans:10, tol:0.01, wrong:[[0.1,'SAI_MAU_SO'],[640,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Số video = ngân sách ÷ chi phí mỗi video.','80 ÷ 8 = <b>10 video</b>.'] },
  { type:'mcq', stem:'Một hãng kem chống nắng cho người trẻ muốn dùng tín hiệu thật. Câu thoại nào hợp nhất?',
    options:[{k:'a',t:'"Hoàn hảo cho mọi loại da, không có bất kỳ nhược điểm nào"'},{k:'b',t:'"Được các chuyên gia hàng đầu tin dùng trên khắp thế giới"'},
             {k:'c',t:'"Da mình dầu, bôi hơi bóng lúc đầu, 15 phút sau thì ráo"'},{k:'d',t:'"Sản phẩm số một, đẳng cấp vượt trội so với mọi đối thủ"'}],
    answer:'c', why:{a:'Hứa tuyệt đối là tín hiệu "làm màu" rõ nhất; người trẻ sẽ nghi ngay.',
      b:'Lời chứng mơ hồ, không có người cụ thể, nghe như quảng cáo cũ.',
      c:'Đúng. Người thật, loại da cụ thể, nói cả điểm chưa hoàn hảo và điều xảy ra sau đó.',
      d:'Khẳng định so sánh chung chung vừa khó tin vừa có rủi ro pháp lý.'} },
  { type:'mcq', stem:'Một đồng nghiệp hỏi: "Vậy mình quay ẩu cho thật à?" Câu trả lời đúng nhất?',
    options:[{k:'a',t:'Đúng, càng mộc càng tốt, rung hình và tiếng ồn cũng không sao'},{k:'b',t:'Không, thật là ở nội dung và người nói; âm thanh vẫn phải rõ'},
             {k:'c',t:'Không, vẫn phải quay studio nhưng chọn người mẫu trẻ hơn'},{k:'d',t:'Tuỳ, cứ quay ẩu trước rồi xem số liệu có tốt hơn hay không'}],
    answer:'b', why:{a:'Ẩu làm người xem khó theo dõi; "thật" không đồng nghĩa với kém chất lượng.',
      b:'Đúng. Tín hiệu thật nằm ở ai nói, nói gì, bối cảnh nào — không phải ở hình rung.',
      c:'Đổi người mẫu không đổi được cảm giác dàn dựng.',
      d:'Thử nghiệm là tốt, nhưng thử một biến thể "ẩu" không kiểm tra được giả thuyết chính.'} },
  { type:'mcq', stem:'Video B có bình luận "quảng cáo trá hình à?". Bạn phản hồi thế nào?',
    options:[{k:'a',t:'Xoá bình luận để không ảnh hưởng tới người xem khác'},{k:'b',t:'Nhờ vài tài khoản khác vào bình luận khen để át đi'},
             {k:'c',t:'Im lặng, vì trả lời sẽ khiến bình luận được chú ý hơn'},{k:'d',t:'Nói rõ đây là nhân viên hãng, mời hỏi thêm về đôi giày'}],
    answer:'d', why:{a:'Xoá bình luận bị phát hiện sẽ củng cố đúng nghi ngờ "làm màu".',
      b:'Dựng bình luận giả là đúng thứ người trẻ ghét nhất, và dễ bị lật.',
      c:'Im lặng để câu hỏi treo, người xem sau tự hiểu theo hướng xấu.',
      d:'Đúng. Minh bạch vai trò là tín hiệu thật; nó biến nghi ngờ thành cuộc trò chuyện.'} },
  { type:'mcq', stem:'Chỉ số nào cho thấy video B "chạm" được người xem, không chỉ được xem?',
    options:[{k:'a',t:'Số bình luận hỏi size, giá và nơi mua trên mỗi nghìn lượt xem'},{k:'b',t:'Tổng số lượt xem sau 7 ngày, so với video A cùng thời gian'},
             {k:'c',t:'Số lượt thích trên video, vì thích là thể hiện sự đồng tình'},{k:'d',t:'Số người theo dõi kênh tăng thêm trong tuần đăng video'}],
    answer:'a', why:{a:'Đúng. Câu hỏi mua hàng là tín hiệu ý định, chuẩn hoá theo lượt xem để so được.',
      b:'Lượt xem có thể đến từ quảng cáo; không cho biết người xem có quan tâm tới sản phẩm.',
      c:'Lượt thích dễ có, ít gắn với ý định mua.',
      d:'Theo dõi kênh là tín hiệu quan tâm chung, không đặc hiệu cho sản phẩm.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:kh10-04', skill:'channel', read:'7 phút', t:'Khách trẻ tìm quán ăn trên TikTok — Google của bạn còn đủ không?',
  situation:'Một quán bún chả ở Đà Nẵng đầu tư 2 triệu mỗi tháng để lên top Google Maps, điểm 4,6 sao. Hỏi 40 khách dưới 25 tuổi "bạn biết quán qua đâu", 26 người nói "thấy trên TikTok", 8 người qua Google Maps, 6 người do bạn rủ. Quán chưa có video nào; các video nhắc tới quán đều do khách tự quay.',
  concept:{ name:'Tìm kiếm bằng video',
    body:'Nhiều người trẻ gõ "quán bún chả Đà Nẵng" ngay trên TikTok thay vì Google, vì video cho họ thấy <b>món thật, không khí thật, người thật đang ăn</b>. Với họ, TikTok vừa là mạng xã hội vừa là công cụ tìm kiếm. Việc của quán là đảm bảo khi ai đó tìm, họ thấy nội dung đúng: tên quán rõ, địa chỉ, món nổi bật, giá. Google Maps vẫn cần cho bước cuối — chỉ đường, giờ mở cửa.' },
  example:'26 trên 40 người (65%) đến từ TikTok, nhưng quán không kiểm soát nội dung nào ở đó. Quán quay 3 video ngắn: cận cảnh chả nướng than, bảng giá 35.000đ, đường vào hẻm. Mô tả video ghi đủ "bún chả + tên quán + quận". Đồng thời trả lời bình luận dưới video của khách. Google Maps giữ nguyên để khách tra đường sau khi đã quyết định đi.',
  takeaway:'Người trẻ tìm bằng mắt: hãy có mặt trong kết quả tìm kiếm video, không chỉ trên bản đồ.',
  apply:'Mở TikTok, gõ tên một loại món + quận bạn ở. Nói trong 60 giây: quán nào hiện lên, và vì sao video đó làm bạn muốn đi.',
  mistakes:['Nghĩ TikTok chỉ để giải trí nên không đầu tư mô tả, từ khoá.','Bỏ Google Maps vì "người trẻ không dùng", trong khi đó là bước chỉ đường.'],
  q:[
  { type:'mcq', stem:'Đoán trước: với 26/40 khách trẻ đến từ TikTok, điều quán đang bỏ lỡ lớn nhất là gì?',
    options:[{k:'a',t:'Quán không có nội dung riêng ở nơi khách trẻ đang tìm kiếm'},{k:'b',t:'Quán đang lãng phí 2 triệu cho Google Maps, cần cắt ngay lập tức'},
             {k:'c',t:'Quán chưa thuê người nổi tiếng về ăn thử và quay video'},{k:'d',t:'Quán chưa chạy quảng cáo trả tiền trên TikTok với ngân sách lớn'}],
    answer:'a', why:{a:'Đúng. Khách đang tìm ở TikTok nhưng chỉ thấy video của người khác; quán vắng mặt.',
      b:'Maps vẫn mang 8 khách và là bước chỉ đường; cắt ngay là vội.',
      c:'Người nổi tiếng có thể là một cách, nhưng bước đầu là có nội dung cơ bản của chính quán.',
      d:'Quảng cáo trả tiền không giải quyết chuyện quán không có nội dung tìm thấy được.'} },
  { type:'mcq', stem:'Bạn có 2 triệu mỗi tháng. Bạn chọn làm gì trong tháng tới?',
    options:[{k:'a',t:'Giữ nguyên toàn bộ cho Google Maps vì điểm 4,6 sao đang tốt'},{k:'b',t:'Chuyển toàn bộ sang TikTok, bỏ hẳn Google Maps ngay từ tháng này cho gọn'},
             {k:'c',t:'Giữ Maps ở mức cơ bản, dành phần lớn cho video có tên, giá, địa chỉ'},{k:'d',t:'Chi toàn bộ để in tờ rơi phát ở các trường đại học gần quán'}],
    answer:'c', why:{a:'Maps mang ít khách trẻ; dồn hết vào đó là bỏ qua kênh chính của họ.',
      b:'Maps vẫn cần cho bước chỉ đường; bỏ hẳn làm hỏng bước cuối.',
      c:'Đúng. Mỗi kênh một vai: TikTok để được tìm thấy, Maps để tới được quán.',
      d:'Tờ rơi không phải nơi khách trẻ đang tìm quán theo dữ liệu.'} },
  { type:'calc', stem:'Hỏi 40 khách trẻ, 26 người biết quán qua TikTok. Tỉ lệ là bao nhiêu phần trăm?',
    unit:'%', ans:65, tol:0.1, wrong:[[153.8,'SAI_MAU_SO'],[35,'NHAM_TI_LE_ROI']], errors:['SAI_MAU_SO','NHAM_TI_LE_ROI'],
    steps:['Tỉ lệ = số người qua TikTok ÷ tổng số người được hỏi.','26 ÷ 40 = 0,65 = <b>65%</b>.'] },
  { type:'mcq', stem:'Phần mô tả video nào giúp quán được tìm thấy tốt nhất trên TikTok?',
    options:[{k:'a',t:'"Ngon xỉu luôn mọi người ơi 😍 ghé thử đi nha"'},{k:'b',t:'"#foodtok #fyp #xuhuong #viral #anngon #reviewdoan"'},
             {k:'c',t:'"Bún chả than hoa ở Hải Châu, Đà Nẵng — 35k một phần"'},{k:'d',t:'"Quán ruột của team, ai biết thì biết, không nói thêm"'}],
    answer:'c', why:{a:'Cảm xúc không chứa từ người ta gõ khi tìm.',
      b:'Hashtag chung không khớp với truy vấn "bún chả + nơi chốn".',
      c:'Đúng. Có món, khu vực và giá — đúng những gì người trẻ gõ khi tìm quán.',
      d:'Úp mở làm người tìm không biết đây là quán nào, ở đâu.'} },
  { type:'mcq', stem:'Một tiệm sửa điện thoại ở Cần Thơ hỏi có nên làm video TikTok không. Nên trả lời dựa trên điều gì?',
    options:[{k:'a',t:'Hỏi khách hiện tại biết tiệm qua đâu, tách theo nhóm tuổi'},{k:'b',t:'Có, vì bây giờ mọi ngành hàng đều bắt buộc phải có mặt trên TikTok'},
             {k:'c',t:'Không, vì TikTok chỉ hợp với đồ ăn, thời trang và mỹ phẩm'},{k:'d',t:'Xem đối thủ lớn nhất có TikTok không; nếu có thì làm theo luôn'}],
    answer:'a', why:{a:'Đúng. Quyết định kênh dựa trên nơi khách của chính tiệm đang tìm.',
      b:'"Mọi ngành đều phải" là khuôn mẫu, không phải dữ liệu.',
      c:'Nhiều người tìm cách sửa, so sánh tiệm qua video; loại bỏ ngay là vội.',
      d:'Đối thủ có thể cũng đang đoán; bắt chước không thay cho việc hỏi khách.'} },
  { type:'mcq', stem:'Vì sao không nên bỏ Google Maps dù khách trẻ tìm chủ yếu trên TikTok?',
    options:[{k:'a',t:'Vì Google Maps là kênh miễn phí nên không tốn gì khi giữ lại'},{k:'b',t:'Vì người lớn tuổi vẫn dùng Maps nhiều và họ trả nhiều tiền hơn'},
             {k:'c',t:'Vì TikTok có thể bị cấm bất cứ lúc nào nên cần kênh dự phòng'},{k:'d',t:'Vì khách quyết định trên TikTok rồi vẫn mở Maps để tìm đường'}],
    answer:'d', why:{a:'Quán đang trả 2 triệu cho Maps; "miễn phí" không đúng ở đây.',
      b:'Có thể đúng, nhưng lý do chính trong tình huống là vai trò chỉ đường cho chính khách trẻ.',
      c:'Rủi ro nền tảng là chuyện có thật nhưng không phải lý do chính ở đây.',
      d:'Đúng. Hai kênh nối tiếp nhau trong một hành trình: tìm thấy rồi tới nơi.'} },
  { type:'mcq', stem:'Nhiều video về quán do khách tự quay. Việc nên làm với các video đó?',
    options:[{k:'a',t:'Yêu cầu khách gỡ vì quán không kiểm soát được nội dung'},{k:'b',t:'Mặc kệ, vì đó là chuyện của khách, quán không liên quan'},
             {k:'c',t:'Trả lời bình luận, bổ sung giờ mở cửa và cảm ơn người quay'},{k:'d',t:'Tải lại lên kênh quán như video của mình, không cần ghi nguồn'}],
    answer:'c', why:{a:'Gỡ nội dung tốt của khách là tự bỏ nguồn tìm kiếm quý nhất.',
      b:'Người tìm đọc bình luận; quán vắng mặt ở đó là bỏ lỡ.',
      c:'Đúng. Tham gia nhẹ nhàng, bổ sung thông tin người tìm cần.',
      d:'Dùng lại không xin phép, không ghi nguồn làm mất lòng người quay.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:kh10-05', skill:'insight', read:'7 phút', t:'Phụ huynh mua sữa cho con vì dinh dưỡng — hay vì sợ điều gì?',
  situation:'Một hãng sữa bột trẻ em chạy quảng cáo liệt kê 12 dưỡng chất. Tỉ lệ nhấp thấp. Nhóm nghiên cứu ngồi nghe 15 bà mẹ có con 2–4 tuổi nói chuyện. Câu lặp lại nhiều nhất: "Con mình thấp hơn bạn cùng lớp", "Sợ con biếng ăn", "Lỡ mình chọn sai thì sao". Không ai nhắc tới tên dưỡng chất nào.',
  concept:{ name:'Nỗi lo làm động lực mua',
    body:'Với phụ huynh, nhiều quyết định mua cho con không bắt đầu từ <b>lợi ích</b> mà từ <b>nỗi lo</b>: con chậm lớn, con ốm, con thua bạn, mình là cha mẹ chưa đủ tốt. Danh sách thành phần là bằng chứng họ tìm sau, khi đã có nỗi lo. Hiểu đúng giúp thông điệp bắt đầu từ chỗ họ đang lo, rồi mới đưa bằng chứng. Nhưng cần tránh <b>thổi phồng nỗi sợ</b>: doạ nạt làm mất niềm tin và dễ vi phạm quy định quảng cáo sản phẩm cho trẻ.' },
  example:'Bản mới mở đầu bằng câu một bà mẹ nói: "Bé nhà mình ăn ít, mình cứ lo con thấp hơn các bạn." Sau đó mới là: theo dõi cân nặng, chiều cao theo biểu đồ tăng trưởng, và hỏi bác sĩ nhi. Sản phẩm xuất hiện như một phần của kế hoạch, không phải thuốc thần. Thử 2 bản với 10.000 lượt hiển thị mỗi bản: bản dưỡng chất có 80 lượt nhấp, bản nỗi lo có 180 lượt nhấp.',
  takeaway:'Phụ huynh mua để bớt lo cho con; bắt đầu từ nỗi lo thật, rồi mới đưa bằng chứng — và đừng doạ.',
  apply:'Hỏi một người có con nhỏ: "Điều gì khiến anh/chị lo nhất khi chọn đồ cho bé?" Kể lại câu trả lời trong 60 giây.',
  mistakes:['Mở đầu bằng danh sách thành phần mà phụ huynh chưa hỏi tới.','Khuếch đại nỗi sợ để ép mua, làm mất niềm tin và dễ vi phạm quy định.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao quảng cáo liệt kê 12 dưỡng chất có tỉ lệ nhấp thấp?',
    options:[{k:'a',t:'Phụ huynh không hiểu dưỡng chất nên cần giải thích dài và kỹ hơn'},{k:'b',t:'12 dưỡng chất vẫn còn ít, đối thủ đang nói tới 20 dưỡng chất'},
             {k:'c',t:'Thông điệp không chạm tới nỗi lo đang thúc đẩy họ tìm sữa'},{k:'d',t:'Hình ảnh quảng cáo chưa đủ đẹp nên không ai muốn bấm vào xem'}],
    answer:'c', why:{a:'Giải thích dài hơn vẫn là nói về thứ họ chưa quan tâm tới.',
      b:'Đua số lượng dưỡng chất không trả lời được nỗi lo.',
      c:'Đúng. Không ai trong 15 bà mẹ nhắc dưỡng chất; họ nói về nỗi lo.',
      d:'Không có dữ kiện về hình ảnh; lời của phụ huynh chỉ ra vấn đề ở thông điệp.'} },
  { type:'mcq', stem:'Bạn viết lại câu mở đầu quảng cáo. Bạn chọn câu nào?',
    options:[{k:'a',t:'"Con bạn đang thấp hơn chuẩn? Đừng để quá muộn mới hối hận!"'},{k:'b',t:'"Bé ăn ít, mẹ lo con thấp hơn bạn? Theo dõi tăng trưởng cùng bác sĩ"'},
             {k:'c',t:'"Công thức 12 dưỡng chất vượt trội, số một cho trẻ 2–4 tuổi"'},{k:'d',t:'"Giảm 20% cho hộp lớn, tặng thêm bình nước cho bé yêu"'}],
    answer:'b', why:{a:'Doạ "quá muộn" là thổi phồng nỗi sợ; mất niềm tin và dễ vi phạm quy định.',
      b:'Đúng. Gọi đúng nỗi lo bằng lời của họ, rồi đưa hướng đi có căn cứ.',
      c:'Quay lại cách cũ, và thêm khẳng định "số một" rủi ro.',
      d:'Khuyến mãi không chạm nỗi lo; chỉ kéo người đã định mua.'} },
  { type:'calc', stem:'Bản "dưỡng chất" có 80 lượt nhấp trên 10.000 lượt hiển thị; bản "nỗi lo" có 180 lượt nhấp trên 10.000. Tỉ lệ nhấp của bản "nỗi lo" là bao nhiêu phần trăm?',
    unit:'%', ans:1.8, tol:0.01, wrong:[[180,'SAI_MAU_SO'],[1,'NHAM_DIEM_PHAN_TRAM']], errors:['SAI_MAU_SO','NHAM_DIEM_PHAN_TRAM'],
    steps:['Tỉ lệ nhấp = lượt nhấp ÷ lượt hiển thị.','180 ÷ 10.000 = 0,018 = <b>1,8%</b> (bản cũ 0,8%, hơn 1 điểm phần trăm).'] },
  { type:'mcq', stem:'Một hãng ghế ô tô trẻ em muốn áp dụng bài học. Thông điệp nào hợp nhất?',
    options:[{k:'a',t:'"Khung thép, đai 5 điểm, đạt chuẩn châu Âu, 7 màu lựa chọn"'},{k:'b',t:'"Mỗi năm có hàng nghìn tai nạn — con bạn có thể là người tiếp theo"'},
             {k:'c',t:'"Ghế đẹp nhất thị trường, bé nào ngồi cũng thích mê"'},{k:'d',t:'"Phanh gấp là lúc bố mẹ thót tim — ghế giữ bé chắc, đạt chuẩn"'}],
    answer:'d', why:{a:'Liệt kê thông số trước khi chạm nỗi lo, như bản sữa cũ.',
      b:'Doạ bằng tai nạn là thổi phồng nỗi sợ và thiếu nguồn.',
      c:'Đẹp không phải lý do phụ huynh tìm ghế an toàn.',
      d:'Đúng. Gọi đúng khoảnh khắc lo, rồi đưa bằng chứng cụ thể.'} },
  { type:'mcq', stem:'Vì sao không nên khuếch đại nỗi sợ dù nó làm tăng lượt nhấp ngắn hạn?',
    options:[{k:'a',t:'Vì nỗi sợ chỉ hiệu quả với bố, không hiệu quả với mẹ'},{k:'b',t:'Phụ huynh thấy bị thao túng, mất niềm tin; còn dễ vi phạm quy định'},
             {k:'c',t:'Vì nền tảng quảng cáo luôn chặn mọi nội dung nói về nỗi lo'},{k:'d',t:'Vì nỗi sợ làm giá sản phẩm có vẻ đắt hơn trong mắt khách'}],
    answer:'b', why:{a:'Không có căn cứ phân biệt bố mẹ như vậy.',
      b:'Đúng. Niềm tin là tài sản dài hạn với phụ huynh; doạ nạt phá nó.',
      c:'Nền tảng không chặn mọi nội dung chạm nỗi lo; vấn đề là mức độ và cách nói.',
      d:'Không liên quan trực tiếp tới cảm nhận giá.'} },
  { type:'mcq', stem:'Khi phỏng vấn phụ huynh, câu hỏi nào dễ lộ ra nỗi lo thật nhất?',
    options:[{k:'a',t:'"Anh/chị thích sữa có những dưỡng chất nào cho bé?"'},{k:'b',t:'"Anh/chị sẵn sàng chi bao nhiêu mỗi tháng cho sữa?"'},
             {k:'c',t:'"Anh/chị biết những thương hiệu sữa bột nào hiện nay?"'},{k:'d',t:'"Lần gần nhất anh/chị lo về việc ăn uống của bé là khi nào?"'}],
    answer:'d', why:{a:'Câu hỏi dẫn dắt về dưỡng chất, sẽ nhận câu trả lời theo sách.',
      b:'Hỏi ngân sách không lộ động lực.',
      c:'Hỏi nhận biết thương hiệu, không hỏi động lực.',
      d:'Đúng. Hỏi một lần cụ thể giúp họ kể chuyện thật, lộ ra nỗi lo.'} },
  { type:'mcq', stem:'Sau khi đổi thông điệp, lượt nhấp tăng nhưng tỉ lệ mua không đổi. Bạn nghi điều gì trước?',
    options:[{k:'a',t:'Trang đích vẫn chỉ liệt kê dưỡng chất, không nối tiếp nỗi lo'},{k:'b',t:'Thông điệp nỗi lo thật ra không hiệu quả, nên quay về bản cũ'},
             {k:'c',t:'Phụ huynh nhấp vì tò mò chứ không bao giờ mua qua mạng'},{k:'d',t:'Giá sữa quá cao so với thu nhập của phụ huynh hiện nay'}],
    answer:'a', why:{a:'Đúng. Quảng cáo mở bằng nỗi lo nhưng trang đích quay lại bảng thành phần làm đứt mạch.',
      b:'Lượt nhấp đã tăng; vấn đề nằm ở bước sau, không phải ở thông điệp.',
      c:'"Không bao giờ" là khuôn mẫu; nhiều phụ huynh mua sữa online.',
      d:'Có thể, nhưng giá không đổi trước và sau; kiểm tra chỗ vừa thay đổi trước.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:kh10-06', skill:'channel', read:'7 phút', t:'Một bà mẹ trong nhóm Facebook có sức nặng hơn quảng cáo của bạn?',
  situation:'Một hãng bỉm mới chạy quảng cáo Facebook 3 tháng, chi 60 triệu, có 120 đơn. Cùng lúc, một thành viên trong nhóm "Mẹ bỉm sữa Hà Đông" (khoảng 40.000 thành viên) đăng bài so sánh 4 loại bỉm, có ảnh bé mặc, nhắc hãng này là "thấm tốt, hơi nóng mùa hè". Tuần đó hãng nhận 45 đơn ghi "thấy trong nhóm".',
  concept:{ name:'Tin người đi trước',
    body:'Phụ huynh, nhất là lần đầu làm cha mẹ, không có kinh nghiệm để tự đánh giá. Họ tìm tới <b>người đã đi trước</b>: mẹ có con lớn hơn vài tháng, người cùng khu, cùng hoàn cảnh. Nhóm Facebook mẹ bỉm, nhóm Zalo lớp là nơi những lời khuyên đó được hỏi – đáp mỗi ngày. Lời khuyên ở đây có sức nặng vì người nói không bán hàng và dám nói cả điểm chưa tốt. Thương hiệu không thể mua niềm tin đó; chỉ có thể <b>xứng đáng</b> để được nhắc tới.' },
  example:'Quảng cáo: 60 triệu / 120 đơn = 500.000đ mỗi đơn. Bài trong nhóm: 0 đồng, 45 đơn trong một tuần. Nhưng hãng không thể "đặt" bài như vậy. Việc đúng: gửi mẫu dùng thử cho mẹ thật, không kèm yêu cầu khen; có người trực trả lời câu hỏi trong nhóm với danh tính rõ ràng; và sửa điểm "hơi nóng" mà các mẹ đã nói ra.',
  takeaway:'Phụ huynh tin người đi trước hơn tin hãng: hãy xứng đáng để được nhắc, đừng cố mua lời nhắc.',
  apply:'Nhớ lại lần gần nhất bạn hỏi ý kiến người quen trước khi mua. Nói trong 60 giây vì sao bạn tin họ hơn quảng cáo.',
  mistakes:['Thuê người đóng vai mẹ bỉm vào nhóm khen sản phẩm.','Coi nhóm Facebook chỉ là nơi đăng quảng cáo, bỏ qua lời góp ý trong đó.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao một bài đăng trong nhóm mang về 45 đơn trong một tuần?',
    options:[{k:'a',t:'Nhóm có 40.000 thành viên nên bài nào cũng tiếp cận được rất nhiều người'},{k:'b',t:'Người viết là mẹ thật, không bán hàng, dám nói cả điểm chưa tốt'},
             {k:'c',t:'Bài đăng có ảnh bé dễ thương nên thu hút sự chú ý hơn quảng cáo'},{k:'d',t:'Facebook ưu tiên bài trong nhóm hơn quảng cáo trả tiền của hãng'}],
    answer:'b', why:{a:'Quy mô nhóm giúp tiếp cận, nhưng quảng cáo cũng tiếp cận nhiều người mà ra ít đơn hơn.',
      b:'Đúng. Niềm tin đến từ người đi trước, không có lợi ích bán hàng, nói cả điểm yếu.',
      c:'Ảnh bé có giúp, nhưng không giải thích sức thuyết phục của lời so sánh.',
      d:'Cơ chế phân phối không giải thích vì sao người đọc quyết định mua.'} },
  { type:'mcq', stem:'Sếp muốn thuê 20 tài khoản đóng vai mẹ bỉm vào nhóm khen sản phẩm. Bạn đề xuất gì?',
    options:[{k:'a',t:'Làm, nhưng chỉ dùng 5 tài khoản để khó bị phát hiện hơn'},{k:'b',t:'Làm, vì đối thủ nào cũng đang làm như vậy trong các nhóm'},
             {k:'c',t:'Gửi mẫu thử cho mẹ thật, trực nhóm công khai, sửa lỗi nóng'},{k:'d',t:'Tăng ngân sách quảng cáo lên gấp đôi thay cho việc vào nhóm'}],
    answer:'c', why:{a:'Ít tài khoản giả hơn vẫn là giả; bị lộ trong nhóm mẹ là mất niềm tin cả cộng đồng.',
      b:'"Ai cũng làm" không giảm rủi ro; nhóm mẹ phát hiện và lan truyền rất nhanh.',
      c:'Đúng. Tạo điều kiện để trải nghiệm thật được chia sẻ, minh bạch danh tính.',
      d:'Quảng cáo đang tốn 500.000đ/đơn; gấp đôi không đổi được cơ chế niềm tin.'} },
  { type:'calc', stem:'Quảng cáo chi 60 triệu và mang về 120 đơn. Chi phí cho mỗi đơn là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:500, tol:0.5, wrong:[[2,'SAI_MAU_SO'],[7200,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Chi phí mỗi đơn = tổng chi ÷ số đơn.','60.000 nghìn ÷ 120 = <b>500 nghìn đồng</b>.'] },
  { type:'mcq', stem:'Trong nhóm có bài chê "bỉm hãng X bị hằn đùi bé". Hãng X nên làm gì?',
    options:[{k:'a',t:'Nhờ admin nhóm xoá bài để tránh lan rộng thêm'},{k:'b',t:'Vào bình luận bằng tài khoản cá nhân, bảo mẹ dùng sai size'},
             {k:'c',t:'Im lặng chờ bài trôi, vì phản hồi sẽ làm bài nổi thêm'},{k:'d',t:'Trả lời công khai với danh tính hãng, hỏi size, đổi hàng'}],
    answer:'d', why:{a:'Xoá bài bị lộ sẽ biến một lời chê thành một vụ việc.',
      b:'Giấu danh tính và đổ lỗi cho khách là hai sai lầm chồng lên nhau.',
      c:'Các mẹ khác đọc và chờ xem hãng xử lý thế nào; im lặng là câu trả lời xấu.',
      d:'Đúng. Minh bạch, hỏi rõ, giải quyết — người đọc thấy hãng có trách nhiệm.'} },
  { type:'mcq', stem:'Vì sao lời khuyên trong nhóm mẹ có sức nặng hơn với người lần đầu làm mẹ?',
    options:[{k:'a',t:'Họ chưa có kinh nghiệm tự đánh giá nên dựa vào người đi trước'},{k:'b',t:'Họ không có thời gian xem quảng cáo nên chỉ đọc nhóm Facebook'},
             {k:'c',t:'Họ nghi ngờ mọi thương hiệu, không tin bất kỳ quảng cáo nào'},{k:'d',t:'Họ muốn được thành viên khác công nhận nên mua theo số đông'}],
    answer:'a', why:{a:'Đúng. Thiếu kinh nghiệm + rủi ro cho con → tìm người đã trải qua.',
      b:'Họ vẫn thấy quảng cáo; vấn đề là mức tin, không phải thời gian.',
      c:'"Không tin bất kỳ" là quá tay; quảng cáo vẫn ra 120 đơn.',
      d:'Có yếu tố xã hội, nhưng lý do chính là giảm rủi ro cho con.'} },
  { type:'mcq', stem:'Các mẹ nhắc "hơi nóng mùa hè". Việc nên làm với nhận xét này là gì?',
    options:[{k:'a',t:'Bỏ qua, vì nhìn chung bài vẫn khen sản phẩm thấm tốt'},{k:'b',t:'Đưa vào kế hoạch cải tiến và báo lại nhóm khi đã sửa'},
             {k:'c',t:'Làm quảng cáo khẳng định bỉm "siêu thoáng" để át đi'},{k:'d',t:'Giảm giá mùa hè để bù cho điểm yếu mà khách đã nhận ra'}],
    answer:'b', why:{a:'Điểm yếu được nói công khai sẽ lặp lại ở bài sau nếu không sửa.',
      b:'Đúng. Lắng nghe người đi trước là nguồn cải tiến, và báo lại xây thêm niềm tin.',
      c:'Nói ngược trải nghiệm thật của khách là tự làm mất uy tín.',
      d:'Giảm giá không sửa được bé bị nóng; phụ huynh ưu tiên con hơn tiền.'} },
  { type:'mcq', stem:'Một hãng đồ chơi giáo dục muốn vào nhóm Zalo phụ huynh các lớp mẫu giáo. Cách nào ổn nhất?',
    options:[{k:'a',t:'Xin số điện thoại phụ huynh từ nhà trường để nhắn tin chào hàng'},{k:'b',t:'Nhờ cô giáo gửi link mua hàng vào nhóm lớp kèm mã giảm giá'},
             {k:'c',t:'Tổ chức buổi chơi thử ở trường, phụ huynh tự chia sẻ nếu thấy hay'},{k:'d',t:'Tham gia nhóm bằng tài khoản phụ huynh giả để giới thiệu đồ chơi'}],
    answer:'c', why:{a:'Lấy dữ liệu cá nhân để chào hàng vi phạm quyền riêng tư và làm mất lòng tin.',
      b:'Mượn uy tín cô giáo để bán làm phụ huynh khó chịu và đặt cô vào thế khó.',
      c:'Đúng. Tạo trải nghiệm thật, để lời chia sẻ đến tự nhiên từ người đi trước.',
      d:'Tài khoản giả trong nhóm lớp bị lộ là mất niềm tin ngay lập tức.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:kh10-07', skill:'comm', read:'6 phút', t:'Người dùng là đứa trẻ, người trả tiền là bố mẹ — bạn nói với ai?',
  situation:'Một ứng dụng học tiếng Anh cho trẻ 6–10 tuổi có gói 1.200.000đ/năm. Bản dùng thử 7 ngày: trẻ rất thích, trung bình mở 5 lần mỗi ngày. Nhưng chỉ 4% gia đình mua gói. Phỏng vấn phụ huynh: "Con chơi thì vui, nhưng không biết có học được gì không", "Sợ con dán mắt vào màn hình".',
  concept:{ name:'Người dùng ≠ người mua',
    body:'Trong nhiều sản phẩm cho trẻ, có ít nhất hai vai: <b>người dùng</b> (đứa trẻ) quyết định có thích, có dùng tiếp không; <b>người trả tiền</b> (bố mẹ) quyết định có mua không. Hai người cần hai lý do khác nhau. Trẻ cần vui. Bố mẹ cần thấy <b>tiến bộ</b> và cảm thấy mình kiểm soát được. Làm tốt một vai mà quên vai kia thì sản phẩm hoặc bị bỏ, hoặc không được mua.' },
  example:'Ứng dụng thêm báo cáo tuần gửi qua Zalo cho bố mẹ: "Tuần này bé học 42 từ mới, phát âm đúng 80%." Thêm giới hạn thời gian 30 phút mỗi ngày do bố mẹ đặt. Trong 1.000 gia đình dùng thử tháng sau, 90 gia đình mua gói — từ 4% lên 9%. Trẻ vẫn chơi vui như trước; thứ thay đổi là bố mẹ nay có lý do để trả tiền.',
  takeaway:'Khi người dùng và người trả tiền khác nhau, mỗi người cần một lý do riêng — đừng bắt một thông điệp làm cả hai việc.',
  apply:'Chọn một sản phẩm cho trẻ bạn biết. Nói trong 60 giây: trẻ thích nó vì gì, bố mẹ trả tiền vì gì.',
  mistakes:['Đo thành công bằng mức độ trẻ thích mà không đo lý do bố mẹ trả tiền.','Nói với bố mẹ bằng ngôn ngữ vui nhộn dành cho trẻ.'],
  q:[
  { type:'mcq', stem:'Đoán trước: trẻ mở ứng dụng 5 lần mỗi ngày nhưng chỉ 4% gia đình mua. Vấn đề chính ở đâu?',
    options:[{k:'a',t:'Giá 1.200.000đ quá cao so với thu nhập của gia đình Việt Nam'},{k:'b',t:'Trẻ thích nhưng bố mẹ không thấy con tiến bộ và lo màn hình'},
             {k:'c',t:'Thời gian dùng thử 7 ngày là quá ngắn để trẻ kịp thích ứng'},{k:'d',t:'Ứng dụng chưa đủ vui, cần thêm trò chơi để trẻ ghiền hơn'}],
    answer:'b', why:{a:'Phụ huynh không nói về giá; họ nói về kết quả học và màn hình.',
      b:'Đúng. Người dùng đã hài lòng; người trả tiền thì chưa có lý do.',
      c:'Trẻ đã thích ngay; vấn đề không nằm ở thời gian thích ứng của trẻ.',
      d:'Làm trẻ "ghiền" hơn còn làm tăng nỗi lo màn hình của bố mẹ.'} },
  { type:'mcq', stem:'Bạn chỉ được làm một tính năng trong tháng tới. Bạn chọn gì?',
    options:[{k:'a',t:'Thêm 20 trò chơi mới để trẻ mở ứng dụng nhiều lần hơn'},{k:'b',t:'Giảm giá gói năm còn 800.000đ trong tháng đầu tiên'},
             {k:'c',t:'Thêm nhân vật hoạt hình nổi tiếng để trẻ đòi bố mẹ mua'},{k:'d',t:'Báo cáo tiến bộ gửi bố mẹ, kèm cài giới hạn thời gian'}],
    answer:'d', why:{a:'Trẻ đã thích; thêm trò chơi phục vụ sai vai.',
      b:'Giảm giá không trả lời "con có học được không".',
      c:'Dùng trẻ để ép bố mẹ có thể tăng mua ngắn hạn nhưng làm bố mẹ khó chịu.',
      d:'Đúng. Cho người trả tiền thấy kết quả và quyền kiểm soát.'} },
  { type:'calc', stem:'Tháng sau có 1.000 gia đình dùng thử, 90 gia đình mua gói. Tỉ lệ mua tăng bao nhiêu điểm phần trăm so với mức 4% cũ?',
    unit:'điểm %', ans:5, tol:0.01, wrong:[[125,'NHAM_DIEM_PHAN_TRAM'],[9,'SAI_TINH_TOAN']], errors:['NHAM_DIEM_PHAN_TRAM','SAI_TINH_TOAN'],
    steps:['Tỉ lệ mới = 90 ÷ 1.000 = 9%.','Mức tăng = 9% − 4% = <b>5 điểm phần trăm</b> (tăng tương đối là 125%, đó là con số khác).'] },
  { type:'mcq', stem:'Một hãng giày trẻ em làm quảng cáo. Cách chia thông điệp nào hợp lý?',
    options:[{k:'a',t:'Đèn nháy và nhân vật cho trẻ; đế mềm, đúng size chân cho bố mẹ'},{k:'b',t:'Chỉ nói về đèn nháy vì trẻ sẽ tự đòi bố mẹ mua cho bằng được'},
             {k:'c',t:'Chỉ nói về chất liệu với bố mẹ vì trẻ nhỏ chưa có tiếng nói'},{k:'d',t:'Một thông điệp chung "giày đẹp cho bé" để gọn và dễ nhớ nhất'}],
    answer:'a', why:{a:'Đúng. Mỗi vai một lý do: trẻ muốn đi, bố mẹ yên tâm trả tiền.',
      b:'Bỏ quên người trả tiền; bố mẹ có thể từ chối món không tốt cho chân.',
      c:'Trẻ không chịu đi thì đôi giày bị bỏ xó, lần sau bố mẹ không mua nữa.',
      d:'Thông điệp chung không đủ lý do cho vai nào.'} },
  { type:'mcq', stem:'Ngoài sản phẩm cho trẻ, trường hợp nào cũng có người dùng khác người trả tiền?',
    options:[{k:'a',t:'Một bạn sinh viên tự mua tai nghe bằng tiền để dành của mình'},{k:'b',t:'Một người đi làm tự mua cà phê buổi sáng trên đường đi làm'},
             {k:'c',t:'Con cái mua máy đo huyết áp cho bố mẹ lớn tuổi ở quê'},{k:'d',t:'Một chủ quán tự chọn mua tủ lạnh cho quán của chính mình'}],
    answer:'c', why:{a:'Người mua và người dùng là một.',
      b:'Người mua và người dùng là một.',
      c:'Đúng. Con trả tiền (cần yên tâm), bố mẹ dùng (cần dễ dùng, chữ to).',
      d:'Chủ quán vừa chọn vừa dùng; cùng một vai.'} },
  { type:'mcq', stem:'Báo cáo tuần nên viết thế nào để bố mẹ thấy đáng tiền?',
    options:[{k:'a',t:'"Bé đã chơi 210 phút tuần này, rất chăm chỉ và vui vẻ!"'},{k:'b',t:'"Bé học 42 từ mới, phát âm đúng 80%, cần luyện âm /th/"'},
             {k:'c',t:'"Bé đạt 5 huy hiệu và mở khoá nhân vật khủng long mới!"'},{k:'d',t:'"Cảm ơn bố mẹ đã tin tưởng, hãy gia hạn để bé học tiếp nhé"'}],
    answer:'b', why:{a:'Nhấn thời gian chơi còn làm bố mẹ lo màn hình hơn.',
      b:'Đúng. Kết quả học cụ thể, kèm việc cần làm tiếp — ngôn ngữ của người trả tiền.',
      c:'Huy hiệu là ngôn ngữ của trẻ, không cho bố mẹ biết con học được gì.',
      d:'Lời mời gia hạn không kèm bằng chứng tiến bộ là không đủ lý do.'} },
  { type:'mcq', stem:'Nếu chỉ đo "số lần trẻ mở ứng dụng mỗi ngày", nhóm sản phẩm sẽ dễ mắc sai lầm gì?',
    options:[{k:'a',t:'Tối ưu cho trẻ nghiện hơn, trong khi bố mẹ lại càng lo'},{k:'b',t:'Đánh giá thấp mức độ hài lòng thật sự của trẻ với sản phẩm'},
             {k:'c',t:'Bỏ sót những đứa trẻ dùng máy tính bảng thay vì điện thoại'},{k:'d',t:'Tốn quá nhiều chi phí máy chủ vì lượt mở ứng dụng tăng lên'}],
    answer:'a', why:{a:'Đúng. Chỉ số của người dùng đẩy sản phẩm ngược với nỗi lo của người trả tiền.',
      b:'Số lần mở phản ánh khá tốt việc trẻ thích; vấn đề là thiếu góc nhìn bố mẹ.',
      c:'Thiết bị không phải vấn đề của chỉ số này.',
      d:'Chi phí máy chủ không phải rủi ro chiến lược ở đây.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:kh10-08', skill:'channel', read:'7 phút', t:'Người tỉnh mua ở đâu và tin ai — có giống người thành phố?',
  situation:'Một hãng máy lọc nước bán tốt ở TP.HCM qua website và sàn thương mại điện tử. Mở rộng về Long An và Tiền Giang, hãng chạy cùng loại quảng cáo, được nhiều lượt xem nhưng rất ít đơn. Khảo sát 30 hộ ở thị trấn cho thấy: 21 hộ mua đồ điện ở cửa hàng điện máy quen trong thị trấn, "vì hư thì chạy ra đó là có người sửa".',
  concept:{ name:'Niềm tin gắn với người bán tại chỗ',
    body:'Ở nhiều thị trấn, huyện, việc mua món giá trị không chỉ là mua hàng mà là mua <b>người chịu trách nhiệm</b>: ai lắp, ai sửa, ai đổi khi hỏng. Chủ cửa hàng quen là người có mặt, có tên, có địa chỉ; họ đứng ra bảo đảm. Vì vậy kênh hiệu quả không nhất thiết là kênh rẻ nhất hay hiện đại nhất, mà là kênh gắn với <b>người được tin</b>. Quảng cáo online vẫn có vai trò tạo biết đến, nhưng quyết định thường chốt tại quầy.' },
  example:'21/30 hộ (70%) mua ở điện máy quen. Hãng đổi cách: ký với 15 cửa hàng điện máy thị trấn, đào tạo chủ tiệm lắp và bảo trì, in tên và số điện thoại tiệm lên tem bảo hành. Quảng cáo online kết bằng "Có bán và bảo hành tại [tên tiệm] – thị trấn Cần Giuộc" thay vì nút "Mua ngay". Đơn hàng bắt đầu đến từ tiệm, không phải từ website.',
  takeaway:'Ở tỉnh, người ta mua người bảo đảm cùng với món hàng: đưa sản phẩm vào tay người họ đã tin.',
  apply:'Hỏi một người thân ở quê: lần gần nhất mua đồ điện, họ mua ở đâu và vì sao. Kể lại trong 60 giây.',
  mistakes:['Mang nguyên kênh thành phố về tỉnh rồi kết luận "người tỉnh chưa có nhu cầu".','Coi cửa hàng quen là kênh lạc hậu thay vì là nơi niềm tin đang nằm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao quảng cáo ở Long An có nhiều lượt xem nhưng ít đơn?',
    options:[{k:'a',t:'Người tỉnh không có nhu cầu dùng máy lọc nước như ở thành phố'},{k:'b',t:'Người tỉnh chưa quen mua hàng online nên không biết cách đặt'},
             {k:'c',t:'Họ muốn có người tại chỗ chịu trách nhiệm lắp và sửa khi hỏng'},{k:'d',t:'Giá ở tỉnh phải thấp hơn thành phố thì người dân mới mua'}],
    answer:'c', why:{a:'Lượt xem cao cho thấy có quan tâm; vấn đề không phải nhu cầu.',
      b:'Nhiều người ở tỉnh mua online thành thạo; lý do họ nêu là chuyện sửa chữa.',
      c:'Đúng. Món cần lắp và bảo trì → họ cần người bảo đảm có mặt tại chỗ.',
      d:'Không có dữ kiện về giá; khảo sát nói về người sửa.'} },
  { type:'mcq', stem:'Bạn chọn kênh bán nào cho thị trấn trong quý tới?',
    options:[{k:'a',t:'Tăng ngân sách quảng cáo online gấp đôi để phủ rộng hơn nữa'},{k:'b',t:'Mở một showroom lớn của hãng ở trung tâm tỉnh lỵ'},
             {k:'c',t:'Hợp tác với điện máy quen ở thị trấn, đào tạo họ lắp và sửa'},{k:'d',t:'Giảm giá 30% trên sàn cho khách có địa chỉ ở tỉnh'}],
    answer:'c', why:{a:'Thêm lượt xem không giải quyết chuyện chưa có người bảo đảm tại chỗ.',
      b:'Showroom ở tỉnh lỵ vẫn xa với người ở thị trấn, và họ chưa quen hãng.',
      c:'Đúng. Đưa sản phẩm vào nơi niềm tin đã có sẵn.',
      d:'Giảm giá không thay được người sửa khi máy hỏng.'} },
  { type:'calc', stem:'Khảo sát 30 hộ, 21 hộ mua đồ điện ở cửa hàng quen. Tỉ lệ là bao nhiêu phần trăm?',
    unit:'%', ans:70, tol:0.1, wrong:[[142.9,'SAI_MAU_SO'],[30,'NHAM_TI_LE_ROI']], errors:['SAI_MAU_SO','NHAM_TI_LE_ROI'],
    steps:['Tỉ lệ = số hộ mua ở cửa hàng quen ÷ tổng số hộ.','21 ÷ 30 = 0,7 = <b>70%</b>.'] },
  { type:'mcq', stem:'Quảng cáo online cho vùng tỉnh nên kết thúc bằng lời kêu gọi nào?',
    options:[{k:'a',t:'"Mua ngay trên website, giao hàng toàn quốc miễn phí"'},{k:'b',t:'"Có bán và bảo hành tại điện máy Hưng Phát – Cần Giuộc"'},
             {k:'c',t:'"Nhắn tin để nhận mã giảm giá độc quyền hôm nay"'},{k:'d',t:'"Theo dõi fanpage để cập nhật khuyến mãi mới nhất"'}],
    answer:'b', why:{a:'Giao hàng toàn quốc không trả lời "hư thì ai sửa".',
      b:'Đúng. Nối nhận biết online với người bảo đảm tại chỗ.',
      c:'Mã giảm giá không giải quyết rào cản chính.',
      d:'Theo dõi fanpage là bước xa, không dẫn tới mua.'} },
  { type:'mcq', stem:'Một hãng mỹ phẩm giá thấp (không cần lắp đặt) mở rộng về tỉnh. Bài học "người bảo đảm" áp dụng thế nào?',
    options:[{k:'a',t:'Y hệt: phải có tiệm quen bảo hành cho từng thỏi son bán ra'},{k:'b',t:'Không áp dụng, vì mỹ phẩm thì người tỉnh chỉ mua trên sàn'},
             {k:'c',t:'Người tỉnh không dùng mỹ phẩm nên không cần bàn chuyện kênh'},{k:'d',t:'Cần hỏi lại: với món này họ tin ai — tiệm quen, người bán online?'}],
    answer:'d', why:{a:'Son không cần bảo hành; áp máy móc là sai.',
      b:'"Chỉ mua trên sàn" là suy đoán, chưa hỏi khách.',
      c:'Khuôn mẫu không có căn cứ.',
      d:'Đúng. Nguyên tắc là tìm nơi niềm tin nằm, nhưng câu trả lời tuỳ ngành hàng.'} },
  { type:'mcq', stem:'Chủ tiệm điện máy thị trấn ngại nhận hàng vì "hãng lạ, khách không hỏi". Bạn thuyết phục bằng gì?',
    options:[{k:'a',t:'Đào tạo lắp đặt, hỗ trợ bảo hành nhanh, hàng ký gửi ban đầu'},{k:'b',t:'Chiết khấu cao hơn đối thủ 10% để tiệm có lãi nhiều hơn'},
             {k:'c',t:'Cam kết chạy quảng cáo TV toàn quốc để khách tự tìm tới'},{k:'d',t:'Tặng tiệm một biển hiệu lớn in logo hãng thật nổi bật'}],
    answer:'a', why:{a:'Đúng. Chủ tiệm cũng đang bảo đảm bằng uy tín mình; giảm rủi ro cho họ là chìa khoá.',
      b:'Lãi cao không bù được rủi ro khách quay lại phàn nàn với tiệm.',
      c:'Quảng cáo toàn quốc tốn kém và chưa chắc tạo nhu cầu tại thị trấn này.',
      d:'Biển hiệu không giải quyết nỗi lo bán hàng lạ, hỏng không ai sửa.'} },
  { type:'mcq', stem:'Nhận định nào về người tỉnh là khuôn mẫu cần tránh?',
    options:[{k:'a',t:'Nhiều hộ ở thị trấn chốt món giá trị tại cửa hàng quen'},{k:'b',t:'Với món cần lắp đặt, họ cân nhắc ai sẽ sửa khi hỏng'},
             {k:'c',t:'Người tỉnh không biết mua online nên chỉ có thể bán ở chợ'},{k:'d',t:'Quảng cáo online vẫn giúp họ biết tới thương hiệu mới'}],
    answer:'c', why:{a:'Nhận định có dữ liệu khảo sát đi kèm.',
      b:'Nhận định có căn cứ từ lời khách.',
      c:'Đúng. Đây là khuôn mẫu: nhiều người ở tỉnh mua online, và chợ không phải kênh duy nhất.',
      d:'Nhận định hợp lý: lượt xem cao cho thấy có biết tới.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:kh10-09', skill:'brand', read:'7 phút', t:'Người ngoại thành chọn thương hiệu quen vì bảo thủ — hay vì sợ mất tiền?',
  situation:'Một hãng nước giặt mới rẻ hơn hãng dẫn đầu 15%, chất lượng thử nghiệm tương đương. Ở các tiệm tạp hoá ngoại thành Bình Dương, hàng nằm im. Chủ tiệm kể: "Khách công nhân lương 7–8 triệu, mua sai một can 90.000đ là tiếc mấy bữa ăn. Họ lấy hãng quen cho chắc."',
  concept:{ name:'Thương hiệu quen là bảo hiểm rủi ro',
    body:'Khi mỗi đồng tiền đều có việc, <b>chi phí của một lần mua sai</b> rất lớn so với khoản tiết kiệm được. Rẻ hơn 15% nhưng nếu hỏng thì mất trọn 100% — người mua cân như vậy. Thương hiệu quen giống bảo hiểm: biết chắc kết quả. Đây không phải bảo thủ mà là <b>tính toán hợp lý</b>. Muốn được thử, hãng mới phải hạ rủi ro của lần thử: gói nhỏ, dùng thử miễn phí, đổi trả tại tiệm, hoặc lời bảo đảm của người họ tin.' },
  example:'Can 3 lít hãng mới giá 76.500đ, hãng quen 90.000đ: tiết kiệm 13.500đ. Nhưng nếu giặt không sạch, khách mất 76.500đ và phải mua lại can quen. Hãng mới ra gói 400ml giá 12.000đ, và chủ tiệm được quyền đổi can lớn nếu khách không hài lòng. Rủi ro lần thử giảm từ 76.500đ xuống 12.000đ. Sau hai tháng, số người mua gói nhỏ chuyển sang can lớn bắt đầu tăng.',
  takeaway:'Với người coi trọng từng đồng, rủi ro mua sai nặng hơn khoản được giảm: hạ rủi ro thử trước khi hạ giá.',
  apply:'Nghĩ tới một lần bạn chọn hãng quen dù có hãng rẻ hơn. Nói trong 60 giây bạn sợ điều gì nếu chọn hãng lạ.',
  mistakes:['Gọi việc trung thành với hãng quen là "bảo thủ, chưa được giáo dục".','Chỉ giảm giá sâu hơn mà không hạ rủi ro của lần thử đầu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vì sao khách công nhân không mua nước giặt rẻ hơn 15%?',
    options:[{k:'a',t:'Họ bảo thủ, không muốn thay đổi thói quen đã có từ lâu'},{k:'b',t:'Họ không để ý giá, chỉ lấy hãng thấy nhiều trên TV'},
             {k:'c',t:'Mua sai một can là mất trọn tiền; hãng quen chắc chắn hơn'},{k:'d',t:'Chủ tiệm không giới thiệu vì hãng mới có chiết khấu thấp'}],
    answer:'c', why:{a:'Gán tính cách là bỏ qua lý do chủ tiệm đã nói rất rõ: sợ mất tiền.',
      b:'Họ rất để ý giá — chính vì vậy họ sợ mua sai.',
      c:'Đúng. Đây là tính toán rủi ro hợp lý khi mỗi đồng tiền đều có việc.',
      d:'Không có dữ kiện về chiết khấu; chủ tiệm kể lý do từ phía khách.'} },
  { type:'mcq', stem:'Bạn có ngân sách cho một hành động. Bạn chọn gì?',
    options:[{k:'a',t:'Giảm giá thêm, rẻ hơn hãng quen tới 30% thay vì 15%'},{k:'b',t:'Chạy quảng cáo nói "chất lượng tương đương, giá rẻ hơn"'},
             {k:'c',t:'Tặng quà cho chủ tiệm để họ xếp hàng ở vị trí đẹp hơn'},{k:'d',t:'Ra gói nhỏ giá thấp và cho tiệm đổi hàng nếu khách không ưng'}],
    answer:'d', why:{a:'Rẻ hơn nữa không hạ rủi ro mua sai trọn can, còn làm khách nghi chất lượng.',
      b:'Lời hứa của hãng lạ chính là thứ khách chưa tin.',
      c:'Vị trí đẹp giúp được thấy, nhưng không giải quyết nỗi sợ mua sai.',
      d:'Đúng. Hạ số tiền có thể mất ở lần thử, và thêm bảo đảm tại chỗ.'} },
  { type:'calc', stem:'Can hãng quen 90.000đ, hãng mới rẻ hơn 15%. Khách tiết kiệm được bao nhiêu nghìn đồng mỗi can?',
    unit:'nghìn đồng', ans:13.5, tol:0.05, wrong:[[76.5,'GIAM_GIA_QUEN_BIEN'],[15,'NHAM_DIEM_PHAN_TRAM']], errors:['GIAM_GIA_QUEN_BIEN','NHAM_DIEM_PHAN_TRAM'],
    steps:['Tiết kiệm = giá hãng quen × 15%.','90 × 0,15 = <b>13,5 nghìn đồng</b> (giá hãng mới là 76,5 nghìn).'] },
  { type:'mcq', stem:'Một hãng dầu ăn mới muốn vào tạp hoá ngoại thành. Cách hạ rủi ro thử nào hợp nhất?',
    options:[{k:'a',t:'Chai 250ml giá thấp đặt cạnh quầy thu ngân để dễ mua thử'},{k:'b',t:'Chai 5 lít giảm 20% cho người mua lần đầu tiên'},
             {k:'c',t:'Quảng cáo TV giờ vàng khẳng định "ngon hơn hãng dẫn đầu"'},{k:'d',t:'Tặng móc khoá cho mỗi khách mua can dầu lớn của hãng'}],
    answer:'a', why:{a:'Đúng. Gói nhỏ giá thấp làm số tiền có thể mất ở lần thử rất nhỏ.',
      b:'Can to vẫn là rủi ro lớn; giảm 20% không bù được nếu dùng không hợp.',
      c:'Khẳng định so sánh từ hãng lạ khó tin và tốn kém.',
      d:'Quà nhỏ không hạ rủi ro của món chính.'} },
  { type:'mcq', stem:'Vì sao gọi hành vi này là "bảo thủ" là cách hiểu sai có hại?',
    options:[{k:'a',t:'Vì từ này làm khách tổn thương nếu họ nghe thấy trong quảng cáo'},{k:'b',t:'Vì nó dẫn tới cách "giáo dục" khách thay vì hạ rủi ro cho họ'},
             {k:'c',t:'Vì thật ra người ngoại thành là nhóm thích đổi mới nhất'},{k:'d',t:'Vì người ngoại thành không bao giờ trung thành với thương hiệu'}],
    answer:'b', why:{a:'Có thể đúng, nhưng tác hại chính là hướng hành động sai.',
      b:'Đúng. Hiểu sai lý do → chọn sai giải pháp (thuyết phục thay vì hạ rủi ro).',
      c:'Đi từ khuôn mẫu này sang khuôn mẫu ngược lại, không có căn cứ.',
      d:'Họ đang rất trung thành với hãng quen — đó là dữ kiện của tình huống.'} },
  { type:'mcq', stem:'Sau hai tháng, chỉ số nào cho thấy chiến lược gói nhỏ đang đúng hướng?',
    options:[{k:'a',t:'Tổng số gói nhỏ bán ra tăng mạnh so với tháng đầu tiên'},{k:'b',t:'Số tiệm tạp hoá đồng ý nhận hàng tăng thêm mỗi tuần'},
             {k:'c',t:'Tỉ lệ người mua gói nhỏ quay lại mua can lớn của hãng'},{k:'d',t:'Số lượt nhắc tên hãng trên các nhóm Facebook khu công nghiệp'}],
    answer:'c', why:{a:'Gói nhỏ bán nhiều có thể chỉ là người thử rồi bỏ.',
      b:'Tiệm nhận hàng là điều kiện cần, chưa cho thấy khách chấp nhận.',
      c:'Đúng. Chuyển từ thử sang dùng thật là bằng chứng rủi ro đã được gỡ.',
      d:'Lượt nhắc là tín hiệu phụ, không đo trực tiếp hành vi mua.'} },
  { type:'mcq', stem:'Chủ tiệm được quyền đổi can lớn nếu khách không hài lòng. Điều này hiệu quả vì sao?',
    options:[{k:'a',t:'Vì khách được nhận thêm tiền mặt mỗi khi đổi hàng tại tiệm'},{k:'b',t:'Vì hãng tiết kiệm được chi phí vận chuyển hàng lỗi về kho'},
             {k:'c',t:'Vì chủ tiệm sẽ được hãng thưởng thêm theo mỗi lần đổi trả'},{k:'d',t:'Người khách tin đứng ra bảo đảm, rủi ro mua sai gần như bằng 0'}],
    answer:'d', why:{a:'Không có tiền mặt nào; giá trị là được đổi hàng.',
      b:'Có thể có lợi về hậu cần, nhưng không phải lý do khách dám thử.',
      c:'Không có dữ kiện về thưởng; và thưởng theo đổi trả là khuyến khích sai.',
      d:'Đúng. Kết hợp hạ rủi ro với lời bảo đảm của người quen.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:kh10-10', skill:'insight', read:'7 phút', t:'Chân dung khách của bạn là người thật — hay là một khuôn mẫu?',
  situation:'Nhóm bạn viết chân dung khách cho một chuỗi bánh mì: "Minh, 22 tuổi, Gen Z, thích trend, sống ảo, không trung thành". Sau 2 tuần phỏng vấn 20 khách trẻ tại quầy, 14 người nói mua vì "gần chỗ học, 20 phút là có, giá ổn", chỉ 3 người nhắc tới mạng xã hội. Chân dung cũ không dự đoán được hành vi nào trong số đó.',
  concept:{ name:'Chân dung dựa trên hành vi, không dựa trên nhãn',
    body:'Khuôn mẫu (stereotype) là câu mô tả cả một nhóm bằng vài tính từ quen tai: "Gen Z thích trend", "mẹ bỉm cả tin", "người tỉnh bảo thủ". Nó dễ viết, dễ gật đầu, nhưng <b>không giúp ra quyết định</b> và thường sai. Chân dung tốt trả lời: họ đang cố làm việc gì, trong hoàn cảnh nào, cản trở là gì, họ tin ai, bằng chứng từ đâu. Mỗi dòng nên kèm <b>nguồn</b>: phỏng vấn, số liệu, quan sát. Dòng nào không có nguồn là giả thuyết cần kiểm.' },
  example:'Chân dung mới: "Sinh viên gần trường, có 20 phút giữa hai ca học, cần no và kịp giờ, ngân sách bữa sáng khoảng 25.000đ; chọn quán theo độ nhanh và gần (14/20 người nói vậy)." Từ đó ra quyết định: đặt trước qua Zalo, lấy trong 3 phút. Nhóm bỏ dòng "sống ảo" vì chỉ 3/20 người nhắc và không đổi quyết định nào.',
  takeaway:'Một chân dung tốt dẫn tới quyết định và có nguồn cho từng dòng; tính từ quen tai không làm được điều đó.',
  apply:'Viết lại một câu khuôn mẫu bạn từng nghe về khách hàng thành một câu có hoàn cảnh, việc cần làm và nguồn. Đọc to trong 60 giây.',
  mistakes:['Viết chân dung bằng tính từ về thế hệ, vùng miền, vai trò gia đình.','Giữ lại dòng không có nguồn chỉ vì nghe hợp lý.'],
  q:[
  { type:'mcq', stem:'Đoán trước: vấn đề lớn nhất của chân dung "Gen Z, thích trend, sống ảo" là gì?',
    options:[{k:'a',t:'Chân dung quá ngắn, cần thêm sở thích, thần tượng và màu yêu thích'},{k:'b',t:'Chân dung chọn sai độ tuổi, khách thật lớn tuổi hơn 22 khá nhiều'},
             {k:'c',t:'Chân dung không dựa trên hành vi thật nên không dẫn tới quyết định'},{k:'d',t:'Chân dung cần có ảnh minh hoạ thật đẹp thì cả nhóm mới dễ hình dung ra'}],
    answer:'c', why:{a:'Thêm tính từ vẫn là khuôn mẫu, chỉ dài hơn.',
      b:'Tuổi không sai; sai ở chỗ mô tả bằng nhãn thay vì hành vi.',
      c:'Đúng. 14/20 người mua vì gần và nhanh — chân dung cũ không nói điều đó.',
      d:'Ảnh làm chân dung sinh động nhưng không sửa được nội dung sai.'} },
  { type:'mcq', stem:'Bạn được giao sửa chân dung. Bạn sửa gì trước?',
    options:[{k:'a',t:'Thay các tính từ bằng hoàn cảnh, việc cần làm và nguồn cho từng dòng'},{k:'b',t:'Giữ nguyên chân dung, thêm một chân dung thứ hai cho khách lớn tuổi'},
             {k:'c',t:'Đổi "Gen Z" thành "người trẻ" cho đỡ khuôn mẫu mà vẫn giữ ý chính'},{k:'d',t:'Bỏ hẳn chân dung, chỉ dùng số liệu bán hàng để ra mọi quyết định'}],
    answer:'a', why:{a:'Đúng. Mỗi dòng phải trả lời được "vì sao ta biết" và dẫn tới việc làm.',
      b:'Thêm chân dung mới không sửa chân dung sai.',
      c:'Đổi chữ mà giữ ý vẫn là khuôn mẫu.',
      d:'Số liệu bán hàng cho biết cái gì, không cho biết vì sao; vẫn cần chân dung.'} },
  { type:'calc', stem:'Phỏng vấn 20 khách trẻ, 3 người nhắc tới mạng xã hội. Tỉ lệ là bao nhiêu phần trăm?',
    unit:'%', ans:15, tol:0.1, wrong:[[666.7,'SAI_MAU_SO'],[85,'NHAM_TI_LE_ROI']], errors:['SAI_MAU_SO','NHAM_TI_LE_ROI'],
    steps:['Tỉ lệ = số người nhắc ÷ tổng số người được hỏi.','3 ÷ 20 = 0,15 = <b>15%</b>.'] },
  { type:'mcq', stem:'Dòng nào trong chân dung khách là khuôn mẫu cần viết lại?',
    options:[{k:'a',t:'"Có 20 phút giữa hai ca, chọn quán gần và nhanh (14/20 người)"'},{k:'b',t:'"Ngân sách bữa sáng khoảng 25.000đ (phỏng vấn tại quầy)"'},
             {k:'c',t:'"Đặt qua Zalo nếu lấy được trong 3 phút (thử 1 tuần)"'},{k:'d',t:'"Mẹ bỉm hay cả tin, dễ bị thuyết phục bởi lời khen trên mạng"'}],
    answer:'d', why:{a:'Có hoàn cảnh và nguồn.',
      b:'Có số và nguồn.',
      c:'Có hành vi và cách kiểm.',
      d:'Đúng. Nhãn chung cho cả nhóm, không nguồn, và còn sai: mẹ bỉm tin người đi trước có lý do.'} },
  { type:'mcq', stem:'Một dòng trong chân dung nghe rất hợp lý nhưng chưa có nguồn. Nên xử lý thế nào?',
    options:[{k:'a',t:'Giữ nguyên vì cả nhóm đều thấy đúng, không cần kiểm tra'},{k:'b',t:'Đánh dấu là giả thuyết và lên cách kiểm trong đợt phỏng vấn tới'},
             {k:'c',t:'Xoá luôn vì mọi dòng không có số liệu đều là sai'},{k:'d',t:'Tìm một bài báo nói điều tương tự để làm nguồn cho dòng đó'}],
    answer:'b', why:{a:'Cả nhóm gật đầu thường chính là dấu hiệu của khuôn mẫu.',
      b:'Đúng. Không vứt, không tin ngay — biến thành thứ cần kiểm.',
      c:'Chưa có nguồn không có nghĩa là sai; có thể đúng nhưng chưa kiểm.',
      d:'Nguồn chung về cả thế hệ không chứng minh được hành vi khách của bạn.'} },
  { type:'mcq', stem:'Câu nào về "phụ huynh" là chân dung hành vi, không phải khuôn mẫu?',
    options:[{k:'a',t:'"Phụ huynh thời nay chiều con, con đòi gì cũng mua ngay"'},{k:'b',t:'"Phụ huynh Việt luôn đặt học hành của con lên trên hết"'},
             {k:'c',t:'"Mẹ lần đầu, hỏi nhóm Facebook trước khi mua bỉm (9/12 người)"'},{k:'d',t:'"Phụ huynh tỉnh lẻ không quan tâm tới thương hiệu đồ trẻ em"'}],
    answer:'c', why:{a:'Nhãn chung, không hoàn cảnh, không nguồn.',
      b:'Khẳng định "luôn" cho cả một nhóm — dấu hiệu khuôn mẫu.',
      c:'Đúng. Có hoàn cảnh (mẹ lần đầu), hành vi (hỏi nhóm), và nguồn (9/12).',
      d:'Chồng hai khuôn mẫu (phụ huynh + tỉnh lẻ), không có căn cứ.'} },
  { type:'mcq', stem:'Vì sao khuôn mẫu nguy hiểm hơn việc không có chân dung nào?',
    options:[{k:'a',t:'Vì nó tạo cảm giác đã hiểu khách, khiến nhóm ngừng tìm hiểu tiếp'},{k:'b',t:'Vì khuôn mẫu luôn luôn sai hoàn toàn trong mọi trường hợp'},
             {k:'c',t:'Vì viết khuôn mẫu tốn nhiều thời gian hơn viết chân dung thật'},{k:'d',t:'Vì khách hàng sẽ đọc được chân dung và thấy bị xúc phạm'}],
    answer:'a', why:{a:'Đúng. Không có chân dung thì còn tò mò; có khuôn mẫu thì nhóm tưởng mình đã biết.',
      b:'Khuôn mẫu có khi đúng một phần; nguy ở chỗ nó thay thế việc kiểm tra.',
      c:'Ngược lại: khuôn mẫu viết rất nhanh, đó là lý do nó phổ biến.',
      d:'Chân dung là tài liệu nội bộ; rủi ro chính là quyết định sai.'} }
  ] }

] });
